输出控件
展示计算结果的控件：

图表输出

# UI 端
plotOutput("myplot", height = "400px")

# Server 端
output$myplot &lt;- renderPlot({
    ggplot(iris, aes(Sepal.Length, Sepal.Width, color = Species)) +
        geom_point() +
        theme_minimal()
})



表格输出

# 静态表格
tableOutput("table")
output$table &lt;- renderTable({
    head(iris)
})

# 交互式表格 (DT)
DTOutput("dt_table")
output$dt_table &lt;- renderDT({
    datatable(iris, options = list(pageLength = 5))
})



文本输出

# 普通文本
textOutput("text")
output$text &lt;- renderText({
    paste("结果:", input$n)
})

# 格式化输出
verbatimTextOutput("code")
output$code &lt;- renderPrint({
    summary(iris)
})



HTML 输出

# HTML 内容
htmlOutput("html")
uiOutput("dynamic_ui")

output$html &lt;- renderUI({
    tags$div(
        tags$h3("动态标题"),
        tags$p("这是动态生成的内容")
    )
})

响应式编程
Shiny 的核心是响应式编程：当输入变化时，相关输出自动更新。

reactive() 表达式
用于创建可共享的响应式数据：

server &lt;- function(input, output, session) {
    # 创建响应式数据
    filtered_data &lt;- reactive({
        iris %&gt;%
            filter(Species == input$species)
    })

    # 多个输出共享同一个响应式数据
    output$plot &lt;- renderPlot({
        ggplot(filtered_data(), aes(Sepal.Length, Sepal.Width)) +
            geom_point()
    })

    output$table &lt;- renderTable({
        head(filtered_data())
    })
}



observe() 与 observeEvent()
用于执行副作用（不返回值）：

server &lt;- function(input, output, session) {
    # 监视某个输入的变化
    observe({
        print(paste("当前值:", input$slider))
    })

    # 仅在按钮点击时执行
    observeEvent(input$go_button, {
        showNotification("分析开始！", type = "message")
    })
}



reactiveValues()
创建可修改的响应式值：

server &lt;- function(input, output, session) {
    # 创建响应式值对象
    rv &lt;- reactiveValues(count = 0, data = NULL)

    # 点击按钮时增加计数
    observeEvent(input$add, {
        rv$count &lt;- rv$count + 1
    })

    output$counter &lt;- renderText({
        paste("点击次数:", rv$count)
    })
}



isolate()
阻止响应式依赖：

output$result &lt;- renderText({
    # 仅在按钮点击时更新，slider 变化不触发
    input$go_button

    isolate({
        paste("固定值:", input$slider)
    })
})

