添加进度条和通知

server &lt;- function(input, output, session) {
    observeEvent(input$long_task, {
        # 显示进度条
        withProgress(message = "处理中...", value = 0, {
            for (i in 1:10) {
                incProgress(1 / 10, detail = paste("步骤", i))
                Sys.sleep(0.5)
            }
        })

        # 显示成功通知
        showNotification("处理完成！", type = "message", duration = 3)
    })
}

进阶技巧

模块化开发
将大型应用拆分为模块：

# 定义模块 UI
histogramUI &lt;- function(id) {
    ns &lt;- NS(id)
    tagList(
        sliderInput(ns("bins"), "Bins:", min = 5, max = 50, value = 20),
        plotOutput(ns("plot"))
    )
}

# 定义模块 Server
histogramServer &lt;- function(id, data) {
    moduleServer(id, function(input, output, session) {
        output$plot &lt;- renderPlot({
            hist(data(), breaks = input$bins, col = "#4f46e5")
        })
    })
}

# 在主应用中使用
ui &lt;- fluidPage(
    histogramUI("hist1"),
    histogramUI("hist2")
)

server &lt;- function(input, output, session) {
    histogramServer("hist1", reactive(rnorm(500)))
    histogramServer("hist2", reactive(runif(500)))
}



使用 JavaScript

ui &lt;- fluidPage(
    tags$head(
        tags$script(HTML("
      Shiny.addCustomMessageHandler('alert', function(message) {
        alert(message);
      });
    "))
    ),
    actionButton("show_alert", "显示提示")
)

server &lt;- function(input, output, session) {
    observeEvent(input$show_alert, {
        session$sendCustomMessage("alert", "Hello from R!")
    })
}

批量处理PDF

批量提取文本

# 获取文件夹中所有PDF
pdf_files &lt;- list.files("pdf_folder", pattern = "\\.pdf$", full.names = TRUE)

# 批量提取
results &lt;- lapply(pdf_files, function(file) {
    tryCatch(
        {
            text &lt;- pdf_text(file)
            tibble(
                file = basename(file),
                pages = length(text),
                text = paste(text, collapse = "\n")
            )
        },
        error = function(e) {
            tibble(file = basename(file), pages = NA, text = NA)
        }
    )
})

# 合并结果
all_texts &lt;- bind_rows(results)



并行处理

library(future)
library(furrr)

# 设置并行
plan(multisession, workers = 4)

# 并行提取
results &lt;- future_map(pdf_files, function(file) {
    text &lt;- pdf_text(file)
    tibble(file = basename(file), text = paste(text, collapse = "\n"))
}, .progress = TRUE)

峰谷检测函数

# 定义峰谷检测函数
find_peaks &lt;- function(x, threshold = 1) {
    n &lt;- length(x)
    peaks &lt;- rep(FALSE, n)
    for (i in (threshold + 1):(n - threshold)) {
        if (all(x[i] &gt; x[(i - threshold):(i - 1)]) &&
            all(x[i] &gt; x[(i + 1):(i + threshold)])) {
            peaks[i] &lt;- TRUE
        }
    }
    peaks
}

find_valleys &lt;- function(x, threshold = 1) {
    n &lt;- length(x)
    valleys &lt;- rep(FALSE, n)
    for (i in (threshold + 1):(n - threshold)) {
        if (all(x[i] &lt; x[(i - threshold):(i - 1)]) &&
            all(x[i] &lt; x[(i + 1):(i + threshold)])) {
            valleys[i] &lt;- TRUE
        }
    }
    valleys
}

实用函数封装

#' 快速绘制气泡图
plot_bubble &lt;- function(data, x, y, size, color = NULL,
                        labels = NULL, title = NULL) {
    p &lt;- ggplot(data, aes(x = .data[[x]], y = .data[[y]], size = .data[[size]]))

    if (!is.null(color)) {
        p &lt;- p + geom_point(aes(fill = .data[[color]]),
            shape = 21, alpha = 0.7, color = "white"
        )
    } else {
        p &lt;- p + geom_point(alpha = 0.7, color = "#4f46e5")
    }

    if (!is.null(labels)) {
        p &lt;- p + ggrepel::geom_text_repel(aes(label = .data[[labels]]), size = 3)
    }

    p + scale_size_continuous(range = c(3, 18)) +
        labs(title = title, x = x, y = y) +
        theme_minimal(base_size = 12) +
        theme(plot.title = element_text(face = "bold"))
}

# 使用示例
plot_bubble(country_data, "gdp_per_capita", "gdp_growth", "population",
    color = "region", labels = "country", title = "快速气泡图"
)

