实战案例

案例1：临床试验结果图

# 模拟临床数据
set.seed(42)
clinical &lt;- data.frame(
  patient = 1:90,
  treatment = rep(c("Placebo", "Drug A", "Drug B"), each = 30),
  response = c(
    rnorm(30, 45, 12),
    rnorm(30, 60, 10),
    rnorm(30, 72, 8)
  ),
  gender = sample(c("Male", "Female"), 90, replace = TRUE)
)

# 创建专业的临床结果图
clinical |&gt;
  tidyplot(x = treatment, y = response, color = treatment) |&gt;
  add_mean_bar(alpha = 0.6) |&gt;
  add_sem_errorbar() |&gt;
  add_data_points_jitter(width = 0.2, alpha = 0.5) |&gt;
  add_test_asterisks() |&gt;
  adjust_title("药物疗效比较") |&gt;
  adjust_x_axis_title("治疗组") |&gt;
  adjust_y_axis_title("应答率 (%)") |&gt;
  remove_legend()










案例2：时间序列数据

# 带误差带的时间序列图
time_course |&gt;
  tidyplot(x = day, y = score, color = treatment) |&gt;
  add_mean_line(linewidth = 1) |&gt;
  add_sem_ribbon(alpha = 0.2) |&gt;
  add_data_points(alpha = 0.3, size = 1) |&gt;
  adjust_title("治疗效果时间曲线") |&gt;
  adjust_x_axis_title("时间 (天)") |&gt;
  adjust_y_axis_title("评分")










案例3：多组比较

# 创建分组比较图
study |&gt;
  tidyplot(x = treatment, y = score, color = treatment) |&gt;
  add_boxplot(alpha = 0.3) |&gt;
  add_data_points_jitter() |&gt;
  add_test_pvalue() |&gt;
  split_plot(by = group) |&gt;
  adjust_title("不同亚组的治疗效果")










案例4：相关性分析

study |&gt;
  tidyplot(x = age, y = score, color = treatment) |&gt;
  add_data_points(size = 2.5, alpha = 0.6) |&gt;
  add_curve_fit() |&gt;
  adjust_title("年龄与评分的关系") |&gt;
  adjust_x_axis_title("年龄 (岁)") |&gt;
  adjust_y_axis_title("评分")

高级技巧

与 ggplot2 结合
tidyplots 返回的是 ggplot2 对象，可以继续添加 ggplot2 层：

library(ggplot2)

study |&gt;
  tidyplot(x = treatment, y = score, color = treatment) |&gt;
  add_mean_bar() |&gt;
  add_sem_errorbar() +
  # 添加 ggplot2 层
  geom_hline(yintercept = 50, linetype = "dashed", color = "red") +
  annotate("text", x = 3.5, y = 52, label = "基线", color = "red")










自定义绑图函数

# 创建自定义绑图函数
my_barplot &lt;- function(data, x, y, color) {
  data |&gt;
    tidyplot(x = {{x}}, y = {{y}}, color = {{color}}) |&gt;
    add_mean_bar(alpha = 0.5) |&gt;
    add_sem_errorbar() |&gt;
    add_data_points_jitter() |&gt;
    add_test_asterisks() |&gt;
    remove_legend()
}

# 使用自定义函数
study |&gt;
  my_barplot(treatment, score, treatment)

样式美化

修改样式

使用fp_set_style来修改各内容的样式
使用fp_add_lines来添加线条
更多参数大家需要多看help文档


主要参考的是设置是gpar包样式

data |&gt;
  forestplot(
    labeltext = c(study, deaths_steroid, deaths_placebo, OR),
    clip = c(0.1, 2.5),
    xlog = TRUE
  ) |&gt;
  fp_add_lines() |&gt;
  fp_set_style(
    box = "royalblue",
    line = "darkblue",
    summary = "royalblue",
    align = "lrrr",
    hrz_lines = "#999999"
  ) |&gt;
  fp_add_header(
    study = c("", "Study"),
    deaths_steroid = c("Deaths", "(steroid)") |&gt;
      fp_align_center(),
    deaths_placebo = c("Deaths", "(placebo)") |&gt;
      fp_align_center(),
    OR = c("", fp_align_center("OR"))
  ) |&gt;
  fp_append_row(
    mean = 0.531,
    lower = 0.386,
    upper = 0.731,
    study = "Summary",
    OR = "0.53",
    is.summary = TRUE
  )










对线条自定义
使用fp_add_lines来添加辅助线，lty是线形，lwd是线宽，col是颜色
f_n代表对第几列添加线条，columns设置线条有多宽

data |&gt;
  forestplot(
    labeltext = c(study, deaths_steroid, deaths_placebo, OR),
    clip = c(0.1, 2.5),
    vertices = TRUE,
    xlog = TRUE
  ) |&gt;
  fp_add_lines(
    h_3 = gpar(lty = 2),
    h_11 = gpar(lwd = 1, columns = 1:4, col = "#000044")
  ) |&gt;
  fp_set_style(
    box = "royalblue",
    line = "darkblue",
    summary = "royalblue",
    align = "lrrr",
    hrz_lines = "#999999"
  ) |&gt;
  fp_add_header(
    study = c("", "Study"),
    deaths_steroid = c("Deaths", "(steroid)") |&gt;
      fp_align_center(),
    deaths_placebo = c("Deaths", "(placebo)") |&gt;
      fp_align_center(),
    OR = c("", fp_align_center("OR"))
  ) |&gt;
  fp_append_row(
    mean = 0.531,
    lower = 0.386,
    upper = 0.731,
    study = "Summary",
    OR = "0.53",
    is.summary = TRUE
  )










